357→            val parts = raw.split(":").map { it.trim() }.filter { it.isNotEmpty() }
358→            val nums = parts.mapNotNull { it.toIntOrNull() }
359→            val rgb = when (nums.size) {
360→                3 -> nums
361→                4 -> nums
362→                5 -> nums.drop(1)
363→                else -> return null
364→            }
365→            val r = rgb[0].coerceIn(0, 255)
366→            val g = rgb[1].coerceIn(0, 255)
367→            val b = rgb[2].coerceIn(0, 255)
368→            val a = if (rgb.size >= 4) rgb[3].coerceIn(0, 255) else 255
369→            return (a shl 24) or (r shl 16) or (g shl 8) or b
